def subtract(a, b):
    # Filter out empty intervals and sort
    a_intervals = sorted([interval for interval in a if interval[0] < interval[1]])
    b_intervals = sorted([interval for interval in b if interval[0] < interval[1]])

    if not a_intervals:
        return []

    if not b_intervals:
        return a_intervals

    # Merge overlapping intervals in a
    merged_a = []
    for start, end in a_intervals:
        if merged_a and merged_a[-1][1] >= start:
            merged_a[-1][1] = max(merged_a[-1][1], end)
        else:
            merged_a.append([start, end])

    # Merge overlapping intervals in b
    merged_b = []
    for start, end in b_intervals:
        if merged_b and merged_b[-1][1] >= start:
            merged_b[-1][1] = max(merged_b[-1][1], end)
        else:
            merged_b.append([start, end])

    # Subtract b from a
    result = []
    for a_start, a_end in merged_a:
        current_start = a_start

        for b_start, b_end in merged_b:
            if b_end <= current_start:
                # b interval is completely before current position
                continue
            if b_start >= a_end:
                # b interval is completely after current a interval
                break

            # There is overlap
            if current_start < b_start:
                # Add the part before the b interval
                result.append([current_start, b_start])

            # Move current_start past the b interval
            current_start = max(current_start, b_end)

        # Add remaining part of a interval if any
        if current_start < a_end:
            result.append([current_start, a_end])

    # Merge touching intervals in result
    if not result:
        return []

    final_result = []
    for start, end in result:
        if final_result and final_result[-1][1] == start:
            final_result[-1][1] = end
        else:
            final_result.append([start, end])

    return final_result

